import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../Estilo/Detalhes.css';

function Detalhes() {
  const [data, setData] = useState([]);

  useEffect(() => {
    // Fazendo a requisição HTTP ao Beeceptor
    axios.get('https://app.beeceptor.com/console/listausuarios')
      .then(response => {
        console.log('Dados recebidos:', response.data); // Adicione este log
        setData(response.data); // Supondo que a resposta contenha a lista de usuários
      })
      .catch(error => {
        console.error('Ocorreu um erro ao buscar os dados:', error);
      });
  }, []);

  console.log('Estado data:', data); // Adicione este log para verificar o estado

  return (
    <div className="App min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="w-full max-w-md p-6 bg-white rounded-lg shadow-md">
        <h1 className="text-2xl font-bold mb-6 text-gray-800">Detalhes do Cadastro</h1>
        {data.length === 0 ? (
          <p>Nenhum dado cadastrado.</p>
        ) : (
          data.map((item, index) => (
            <div key={index} className="mb-4 p-4 bg-gray-50 rounded-lg shadow-sm">
              <p><strong>Nome Completo:</strong> {item.nomeCompleto}</p>
              <p><strong>Data de Nascimento:</strong> {item.dataNascimento}</p>
              <p><strong>Telefone:</strong> {item.telefone}</p>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

export default Detalhes;
